245	    /// `(...args: T[]) => R` and for `(a?: A, ...rest: B[]) => R`, and leaves every other signature at 0.
246	    pub(crate) const SIGNATURE_HAS_REST_PARAMETER: u64 = 1;
247	    /// `ObjectFlags`: a class or interface type, an instantiation of one (a reference), a tuple, a mapped type.
248	    pub(crate) const OBJECT_CLASS: u64 = 1;
249	    pub(crate) const OBJECT_INTERFACE: u64 = 2;
250	    pub(crate) const OBJECT_REFERENCE: u64 = 4;
251	    pub(crate) const OBJECT_MAPPED: u64 = 32;
252	    /// `TypeFormatFlags` for `typeToString`: `NoTruncation`, `UseAliasDefinedOutsideCurrentScope`,
253	    /// `AllowUniqueESSymbolType` (the last two are what the checker uses when no flags are given) and `InTypeAlias`.
254	    pub(crate) const PRINT_EXPANDED: u64 = 1 | 16384 | 1_048_576 | 8_388_608;
255	    /// `TupleElementFlags`.
256	    pub(crate) const ELEMENT_OPTIONAL: u64 = 2;
257	    pub(crate) const ELEMENT_REST: u64 = 4;
258	    pub(crate) const ELEMENT_VARIADIC: u64 = 8;
259	}
260	
261	tokio::task_local! {
262	    /// The requests the component being answered has sent, so a debug line can say what each one cost.
263	    pub(crate) static REQUESTS: std::sync::Arc<std::sync::atomic::AtomicU64>;
264	}
265	
266	/// One checker session bound to a snapshot and project.
267	pub(crate) struct Rpc {
268	    client: Client,
269	    deadline: Duration,
270	    snapshot: u64,
271	    project: String,
272	    /// The compiler options the program was built with, for a snapshot that adds files to it ([`Rpc::layered`]).
273	    options: Value,
274	    /// Every call and its answer, when the caller asked to record a replay fixture; shared with a layered snapshot.
275	    recording: Option<Arc<Mutex<Vec<Value>>>>,
276	    calls: Arc<Mutex<BTreeMap<String, u64>>>,
277	}
278	
279	/// A diagnostic the checker reports for a file: where it starts and what it says.
280	#[derive(Debug, Clone, Deserialize)]
281	#[serde(rename_all = "camelCase")]
282	pub(crate) struct FileDiagnostic {
283	    /// The file the error is in, which is not always the file asked about.
284	    pub file_name: String,
285	    pub start_position: Position,
286	    /// `DiagnosticCategory`: warning 0, error 1, suggestion 2, message 3.
287	    pub category: u8,
288	    /// The message; a chain of messages arrives as an object, of which only the first is shown.
289	    pub text: Value,
290	}
291	
292	impl FileDiagnostic {
293	    pub(crate) fn is_error(&self) -> bool {
294	        self.category == 1
295	    }
296	
297	    pub(crate) fn message(&self) -> String {
298	        match &self.text {
299	            Value::String(text) => text.clone(),
300	            other => other.get("messageText").and_then(Value::as_str).unwrap_or("a type error").to_string(),
301	        }
302	    }
303	}
304	
305	/// A position in a file, zero-based.
306	#[derive(Debug, Clone, Copy, Deserialize)]
307	pub(crate) struct Position {
308	    pub line: usize,
309	}
