311	impl Rpc {
312	    pub(crate) async fn open(
313	        client: Client,
314	        deadline: Duration,
315	        tsconfig: Option<&str>,
316	        root_files: &[String],
317	        record: bool,
318	    ) -> Result<Rpc, CallError> {
319	        let options = Rpc::prepare(&client, deadline, tsconfig).await?;
320	        Rpc::open_with(client, deadline, &options, root_files, record).await
321	    }
322	
323	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
324	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
325	    /// numeric ones.
326	    pub(crate) async fn prepare(
327	        client: &Client,
328	        deadline: Duration,
329	        tsconfig: Option<&str>,
330	    ) -> Result<Value, CallError> {
331	        let rpc = Rpc {
332	            client: client.clone(),
333	            deadline,
334	            snapshot: 0,
335	            project: String::new(),
336	            options: Value::Null,
337	            recording: None,
338	            calls: Arc::default(),
339	        };
340	        rpc.call("initialize", Value::Null).await?;
341	        Ok(match tsconfig {
342	            Some(file) => {
343	                let parsed: Value = decode(&rpc.call("parseConfigFile", json!({ "file": file })).await?)?;
344	                parsed.get("options").cloned().unwrap_or_else(default_options)
345	            }
346	            None => default_options(),
347	        })
348	    }
349	
350	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
351	    pub(crate) async fn open_with(
352	        client: Client,
353	        deadline: Duration,
354	        options: &Value,
355	        root_files: &[String],
356	        record: bool,
357	    ) -> Result<Rpc, CallError> {
358	        let rpc = Rpc {
359	            client,
360	            deadline,
361	            snapshot: 0,
362	            project: String::new(),
363	            options: options.clone(),
364	            recording: record.then(Arc::default),
365	            calls: Arc::default(),
366	        };
367	        rpc.created(json!({ "createPrograms": [{ "rootFiles": root_files, "compilerOptions": options }] })).await
368	    }
369	
370	    /// A new snapshot of the same program with `files` added, held in the checker's memory and never written to disk:
371	    /// each is a root file, keyed by its absolute path. The calls on it count, and are recorded, with this one's.
372	    pub(crate) async fn layered(&self, root_files: &[String], files: &[(String, String)]) -> Result<Rpc, CallError> {
373	        let rpc = Rpc {
374	            client: self.client.clone(),
375	            deadline: self.deadline,
376	            snapshot: 0,
377	            project: String::new(),
378	            options: self.options.clone(),
379	            recording: self.recording.clone(),
380	            calls: self.calls.clone(),
381	        };
382	        let mut roots = root_files.to_vec();
383	        roots.extend(files.iter().map(|(path, _)| path.clone()));
384	        let layer: serde_json::Map<String, Value> =
385	            files.iter().map(|(path, text)| (path.clone(), Value::String(text.clone()))).collect();
386	        rpc.created(json!({
387	            "fileSystem": { "kind": "layer", "files": layer },
388	            "createPrograms": [{ "rootFiles": roots, "compilerOptions": self.options }],
389	        }))
390	        .await
391	    }
392	
393	    /// The snapshot after this one with `changed` and `deleted` read again from the disk and, given `roots`, its program
394	    /// rooted there instead, built at once (`updateSnapshot` with `ensurePrograms`). Files the program has not changed
395	    /// are kept as parsed: the checker re-reads only what it is told about, and a synthetic program sees even that
396	    /// only when it is rebuilt. This snapshot stays alive until it is released.
397	    pub(crate) async fn updated(
398	        &self,
399	        changed: &[String],
400	        deleted: &[String],
401	        roots: Option<&[String]>,
402	    ) -> Result<Rpc, CallError> {
403	        let mut changes = serde_json::Map::new();
404	        if !changed.is_empty() || !deleted.is_empty() {
405	            changes.insert("fileNotifications".to_string(), json!({ "changed": changed, "deleted": deleted }));
406	        }
407	        if let Some(roots) = roots {
408	            changes.insert(
409	                "reconfigurePrograms".to_string(),
410	                json!([{ "id": self.project, "rootFiles": roots, "compilerOptions": self.options }]),
411	            );
412	        }
413	        changes.insert("ensurePrograms".to_string(), Value::Bool(true));
414	        let response: SnapshotResponse =
415	            decode(&self.call("updateSnapshot", json!({ "snapshot": self.snapshot, "changes": changes })).await?)?;
416	        // The response lists only the projects it replaced; the synthetic program keeps its id.
417	        let project = response.projects.into_iter().next().map_or_else(|| self.project.clone(), |project| project.id);
418	        Ok(Rpc {
419	            client: self.client.clone(),
420	            deadline: self.deadline,
421	            snapshot: response.snapshot,
422	            project,
423	            options: self.options.clone(),
424	            recording: self.recording.clone(),
425	            calls: Arc::default(),
426	        })
427	    }
428	
429	    /// Every file the snapshot's program read, as the checker names them.
430	    pub(crate) async fn source_file_names(&self) -> Result<Vec<String>, CallError> {
431	        self.scoped("getSourceFileNames", json!({})).await
432	    }
433	
434	    /// This session bound to the snapshot `createSnapshot` makes from `params`, and to its one project.
435	    async fn created(mut self, params: Value) -> Result<Rpc, CallError> {
436	        let response: SnapshotResponse = decode(&self.call("createSnapshot", params).await?)?;
437	        let project = response
438	            .projects
439	            .into_iter()
440	            .next()
441	            .ok_or_else(|| CallError::Rejected("createSnapshot returned no project".to_string()))?;
442	        self.snapshot = response.snapshot;
443	        self.project = project.id;
444	        Ok(self)
445	    }
446	
447	    pub(crate) async fn release(&self) {
448	        self.call("release", json!({ "snapshot": self.snapshot })).await.ok();
449	    }
450	
451	    /// The recorded calls as a JSON array, or `None` when recording was off.
452	    pub(crate) fn recording(&self) -> Option<Value> {
453	        let log = self.recording.as_ref()?.lock().ok()?;
454	        Some(Value::Array(log.clone()))
455	    }
456	
457	    /// Requests sent so far, by method.
458	    pub(crate) fn calls(&self) -> BTreeMap<String, u64> {
459	        self.calls.lock().map(|calls| calls.clone()).unwrap_or_default()
460	    }
461	
462	    /// One request, its answer as the JSON text it arrived as: [`decode`] parses it once, into the shape the caller
463	    /// expects.
464	    async fn call(&self, method: &str, params: Value) -> Result<Box<RawValue>, CallError> {
465	        if let Ok(mut calls) = self.calls.lock() {
466	            *calls.entry(method.to_string()).or_default() += 1;
467	        }
468	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
469	        let Some(log) = &self.recording else {
470	            return self.client.request_raw(method, params, self.deadline).await.map_err(classify);
471	        };
472	        let answer = self.client.request_raw(method, params.clone(), self.deadline).await.map_err(classify)?;
473	        let result: Value = decode(&answer)?;
474	        if let Ok(mut log) = log.lock() {
475	            log.push(json!({ "method": method, "params": params, "result": result }));
476	        }
477	        Ok(answer)
478	    }
479	
480	    async fn scoped<T: DeserializeOwned>(&self, method: &str, extra: Value) -> Result<T, CallError> {
481	        decode(&self.scoped_text(method, extra).await?)
482	    }
483	
484	    /// A request about this snapshot and project, its answer left as text.
485	    async fn scoped_text(&self, method: &str, extra: Value) -> Result<Box<RawValue>, CallError> {
486	        let mut params = json!({ "snapshot": self.snapshot, "project": self.project });
487	        if let (Some(base), Value::Object(extra)) = (params.as_object_mut(), extra) {
488	            base.extend(extra);
489	        }
490	        self.call(method, params).await
491	    }
492	
493	    pub(crate) async fn source_file_symbol(&self, file: &str) -> Result<Option<SymbolInfo>, CallError> {
494	        self.scoped("getSymbolOfSourceFile", json!({ "file": file })).await
495	    }
