529	    pub(crate) async fn declared_type_of_symbol(&self, symbol: &Value) -> Result<TypeInfo, CallError> {
530	        self.scoped("getDeclaredTypeOfSymbol", json!({ "symbol": symbol })).await
531	    }
532	
533	    /// The type errors in a file of the program.
534	    pub(crate) async fn semantic_diagnostics(&self, file: &str) -> Result<Vec<FileDiagnostic>, CallError> {
