538	    /// The symbol that declares a type: the interface, class, enum member or unique symbol behind it.
539	    pub(crate) async fn symbol_of_type(&self, type_id: u64) -> Result<Option<SymbolInfo>, CallError> {
540	        self.scoped("getSymbolOfType", json!({ "objectId": type_id })).await
541	    }
542	
543	    /// The types a class or interface extends, instantiated as it names them (`Omit<HTMLAttributes<HTMLDivElement>, "color">`);
544	    /// none for a type that is not a class or interface.
