554	    /// The generic type a reference instantiates; for a tuple reference, the tuple type that holds its element flags.
555	    pub(crate) async fn target_of_type(&self, type_id: u64) -> Result<TypeInfo, CallError> {
556	        self.scoped("getTargetOfType", json!({ "objectId": type_id })).await
557	    }
