563	    /// Whether each property is declared `readonly`, in one round trip.
564	    pub(crate) async fn readonly_symbols(&self, symbols: &[&Value]) -> Result<Vec<bool>, CallError> {
565	        let requests = symbols.iter().map(|symbol| ("isReadonlySymbol", json!({ "symbol": symbol }))).collect();
566	        self.batch(requests).await?.iter().map(|answer| decode(answer)).collect()
567	    }
568	
569	    /// Several requests in one round trip. A request the checker rejects fails the batch: nothing here asks for one
570	    /// that may legitimately fail.
571	    pub(crate) async fn batch(&self, requests: Vec<(&str, Value)>) -> Result<Vec<Box<RawValue>>, CallError> {
572	        let wanted = requests.len();
573	        let scoped: Vec<Value> = requests
574	            .into_iter()
575	            .map(|(method, mut params)| {
576	                if let Value::Object(map) = &mut params {
577	                    map.insert("snapshot".to_string(), json!(self.snapshot));
578	                    map.insert("project".to_string(), json!(self.project));
579	                }
580	                json!({ "method": method, "params": params })
581	            })
582	            .collect();
583	        let mut answers = Vec::with_capacity(wanted);
584	        let mut token: Option<String> = None;
585	        loop {
586	            let mut params = json!({ "requests": scoped });
587	            if let (Some(token), Some(map)) = (&token, params.as_object_mut()) {
588	                map.insert("continuationToken".to_string(), json!(token));
589	            }
590	            let page: BatchPage = decode(&self.call("batchRequests", params).await?)?;
591	            for response in page.responses {
592	                if let Some(error) = response.error {
593	                    return Err(CallError::Rejected(error));
594	                }
595	                answers.push(response.result.unwrap_or_else(|| RawValue::NULL.to_owned()));
596	            }
597	            match page.continuation_token {
598	                Some(next) => token = Some(next),
599	                None => break,
600	            }
601	        }
602	        if answers.len() != wanted {
603	            return Err(CallError::Rejected(format!("a batch of {wanted} requests got {} answers", answers.len())));
604	        }
605	        Ok(answers)
606	    }
607	
