630	    /// The call and construct signatures, the properties and the index signatures of a type, in one round trip.
631	    pub(crate) async fn object_members(&self, type_id: u64) -> Result<ObjectMembers, CallError> {
632	        let requests = vec![
633	            ("getSignaturesOfType", json!({ "type": type_id, "kind": SignatureKind::Call as u8 })),
634	            ("getSignaturesOfType", json!({ "type": type_id, "kind": SignatureKind::Construct as u8 })),
635	            ("getPropertiesOfType", json!({ "type": type_id })),
636	            ("getIndexInfosOfType", json!({ "type": type_id })),
637	        ];
638	        let mut answers = self.batch(requests).await?.into_iter();
639	        let mut next = || answers.next().ok_or_else(|| CallError::Rejected("a short batch".to_string()));
640	        Ok(ObjectMembers {
641	            calls: decode(&next()?)?,
642	            constructs: decode(&next()?)?,
643	            properties: decode(&next()?)?,
644	            indexes: decode(&next()?)?,
645	        })
646	    }
647	
648	    pub(crate) async fn alias_symbol(&self, type_id: u64) -> Result<Option<SymbolInfo>, CallError> {
649	        self.scoped("getAliasSymbolOfType", json!({ "objectId": type_id })).await
650	    }
651	
