656	    /// The type as written inside a type alias declaration, and never cut short: an alias at the top is printed as what
657	    /// it stands for (`(value?: string) => void`, not `Handler`), and a long type is printed to its end.
658	    pub(crate) async fn type_to_string_expanded(&self, type_id: u64) -> Result<String, CallError> {
659	        self.scoped("typeToString", json!({ "type": type_id, "flags": flag::PRINT_EXPANDED })).await
660	    }
661	}
