663	fn default_options() -> Value {
664	    // Numeric enum values: JSX preserve, ESNext modules, bundler resolution, ES2022.
665	    json!({ "jsx": 1, "module": 99, "moduleResolution": 100, "target": 9, "strict": true, "skipLibCheck": true, "noEmit": true })
