668	/// An answer parsed from its text straight into `T`, in one pass.
669	pub(crate) fn decode<T: DeserializeOwned>(answer: &RawValue) -> Result<T, CallError> {
670	    serde_json::from_str(answer.get())
671	        .map_err(|error| CallError::Rejected(format!("unexpected response shape: {error}")))
672	}
