//! One component's props from the checker: the export's call signature, its first parameter's type, that type's
//! properties.

use std::sync::Arc;

use caliper_docgen_core::types::ComponentExport;
use caliper_docgen_core::types::semantic::{PropInterner, SemanticProp};

use crate::Target;
use crate::convert::{Converter, declared_in, without_undefined};
use crate::declared::Asked;
use crate::instantiate::{self, Instantiation};
use crate::rpc::{CallError, Rpc, SignatureKind, SymbolInfo, TypeInfo, flag};

pub(crate) enum Answer {
    Props(Props),
    /// The component keeps its structural result, for this reason.
    Fallback(String),
    /// A generic component, whose props are read from an instantiation of it ([`crate::instantiate`]).
    Instantiate(Instantiation),
}

/// What the checker says about one component's props type.
pub(crate) struct Props {
    pub(crate) props: Vec<Arc<SemanticProp>>,
    /// See [`caliper_docgen_core::types::semantic::SemanticComponent::composes`].
    pub(crate) composes: Option<Vec<String>>,
}

/// What `@types/react` declares (`key`, `ref`, `children` on `PropsWithChildren`, HTML attributes). Reported with the
/// flag set when the request asks for the name; what to do with them is the session's policy, not ours.
fn is_react_declared(property: &SymbolInfo) -> bool {
    property.declarations.iter().any(|declaration| declared_in(declaration).contains("/@types/react/"))
}

fn fallback(reason: &str) -> Result<Answer, CallError> {
    Ok(Answer::Fallback(reason.to_string()))
}

/// A module as the checker reads it: its own symbol, whose declaration names its file in the checker's spelling, and
/// its exports.
pub(crate) struct Module {
    pub(crate) symbol: SymbolInfo,
    pub(crate) exports: Vec<SymbolInfo>,
}

impl Module {
    /// Whether one of `symbol`'s declarations is in this module's file.
    fn declares(&self, symbol: &SymbolInfo) -> bool {
        let files: Vec<&str> = self.symbol.declarations.iter().map(|declaration| declared_in(declaration)).collect();
        symbol.declarations.iter().any(|declaration| files.contains(&declared_in(declaration)))
    }
}

/// The symbol `export` names in `module`: the export of exactly that name, through an alias to what it aliases, then
/// each property an attached sub-component is reached through. `Err` says why there is none, or why it is not the
/// component the extractor found: one declared in another file.
async fn exported_symbol(
    rpc: &Rpc,
    module: &Module,
    export: &ComponentExport,
) -> Result<Result<SymbolInfo, String>, CallError> {
    let Some(symbol) = module.exports.iter().find(|symbol| symbol.name == export.name) else {
        return Ok(Err(format!("the checker finds no export `{}` in its module", export.name)));
    };
    let mut symbol = if symbol.flags & flag::SYMBOL_ALIAS != 0 {
        rpc.aliased_symbol(&symbol.reference).await?
    } else {
        symbol.clone()
    };
    for member in &export.members {
        let parent = rpc.type_of_symbol(&symbol.reference).await?;
        let Some(property) = rpc.properties(parent.id).await?.into_iter().find(|property| property.name == *member)
        else {
            return Ok(Err(format!("the checker finds no property `{member}` on the export `{}`", export.name)));
        };
        symbol = property;
    }
    if !module.declares(&symbol) {
        return Ok(Err(format!("the export `{export}` is declared in another file")));
    }
    Ok(Ok(symbol))
}

/// The component's symbol: the first export the extractor recorded for it that the checker finds. Never another
/// export, such as the module's `default` when `default` is not one of them.
async fn component_symbol(
    rpc: &Rpc,
    module: &Module,
    target: &Target,
) -> Result<Result<(SymbolInfo, ComponentExport), String>, CallError> {
    let mut reasons = Vec::new();
    for export in &target.exports {
        match exported_symbol(rpc, module, export).await? {
            Ok(symbol) => return Ok(Ok((symbol, export.clone()))),
            Err(reason) => reasons.push(reason),
        }
    }
    Ok(Err(if reasons.is_empty() { "not exported by its module".to_string() } else { reasons.join("; ") }))
}

pub(crate) async fn props_of(
    rpc: &Rpc,
    converter: &Converter,
    interner: &PropInterner,
    module: &Module,
    target: &Target,
) -> Result<Answer, CallError> {
    let (symbol, export) = match component_symbol(rpc, module, target).await? {
        Ok(found) => found,
        Err(reason) => return Ok(Answer::Fallback(reason)),
    };

    let component = rpc.type_of_symbol(&symbol.reference).await?;
    let signatures = rpc.signatures(component.id, SignatureKind::Call).await?;
    let [signature] = signatures.as_slice() else {
        return fallback(if signatures.is_empty() {
            "no call signature (class or non-function component)"
        } else {
            "overloaded call signatures"
        });
    };
    let parameters = rpc.parameters(signature.id).await?;
    let Some(first) = parameters.first() else { return fallback("takes no props parameter") };
    if let Some(arguments) = instantiate::default_arguments(rpc, signature).await? {
        if !export.members.is_empty() {
            return fallback("a generic sub-component reached through its parent's property is not instantiated");
        }
        return Ok(Answer::Instantiate(Instantiation { export: export.name, arguments }));
    }

    let props_type = rpc.type_of_symbol(&first.reference).await?;
    Ok(props_of_type(rpc, converter, interner, &props_type, target).await?.map_or_else(Answer::Fallback, Answer::Props))
}

/// The props a component's props type holds, or why the component keeps its structural result.
pub(crate) async fn props_of_type(
    rpc: &Rpc,
    converter: &Converter,
    interner: &PropInterner,
    props_type: &TypeInfo,
    target: &Target,
) -> Result<Result<Props, String>, CallError> {
    if props_type.flags & (flag::ANY | flag::UNKNOWN | flag::UNION | flag::TYPE_PARAMETER) != 0 {
        return Ok(Err("props type is any, unknown, generic or a union".to_string()));
    }

    let own: Vec<SymbolInfo> = rpc
        .properties(props_type.id)
        .await?
        .into_iter()
        .filter(|property| {
            !is_react_declared(property)
                || target.react_wanted.as_ref().is_none_or(|wanted| wanted.contains(&property.name))
        })
        .collect();
    let references: Vec<_> = own.iter().map(|property| &property.reference).collect();
    let types = if references.is_empty() { Vec::new() } else { rpc.types_of_symbols(&references).await? };

    let converted = converter.convert_roots(&types).await?;
    // React's own descriptions and tags are the structural pass's to give, and its props are most of a component's.
    let asked: Vec<Asked<'_>> = own
        .iter()
        .map(|property| {
            let react_declared = is_react_declared(property);
            Asked {
                property,
                description: !react_declared && !target.described.contains(&property.name),
                tags: !react_declared,
            }
        })
        .collect();
    let declared = converter.declared(&asked).await?;
    let mut props = Vec::with_capacity(own.len());
    for ((property, prop_type), declared) in own.iter().zip(converted).zip(declared) {
        let required = property.flags & flag::SYMBOL_OPTIONAL == 0;
        props.push(interner.share(SemanticProp {
            name: property.name.clone(),
            prop_type: without_undefined(prop_type, !required),
            required,
            description: declared.description,
            tags: declared.tags,
            parent: declared.parent,
            declarations: declared.declarations,
            react_declared: is_react_declared(property),
        }));
    }
    let composes = converter.composes(props_type).await?;
    Ok(Ok(Props { props, composes }))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn property(declaration: &str) -> SymbolInfo {
        SymbolInfo {
            reference: serde_json::Value::Null,
            name: "x".to_string(),
            flags: 4,
            declarations: vec![declaration.to_string()],
            parent: None,
        }
    }

    #[test]
    fn the_declaring_path_is_what_follows_the_node_id_and_position() {
        assert_eq!(
            declared_in("48.264./proj/node_modules/@types/react/index.d.ts"),
            "/proj/node_modules/@types/react/index.d.ts"
        );
        assert_eq!(declared_in("garbage"), "");
    }

    #[test]
    fn only_properties_declared_in_types_react_are_excluded() {
        assert!(is_react_declared(&property("1.2./p/node_modules/@types/react/index.d.ts")));
        assert!(!is_react_declared(&property("1.2./p/src/button.tsx")));
        assert!(!is_react_declared(&property("1.2./p/node_modules/@chakra-ui/react/dist/index.d.ts")));
    }
}
//! TypeScript 7.1 checker backend, on by default (ADR 0026; `--no-checker` turns it off).
//!
//! Asks TypeScript's checker for the props of each component the structural pass found, and hands
//! `caliper-docgen-core` a [`SemanticOutcome`] to merge (ADR 0006, ADR 0007). The checker is the `tsrs` crates, linked
//! in and run on a thread of their own; an explicit `tsc_path` runs that binary as a `tsc --api` process instead
//! (through `caliper-docgen-tsc-client`), which is how the tests and the parity gate run the Go checker. It is always
//! compiled in and enabled at run time. Any failure to start or finish (a missing or unpinned binary, a crash, a
//! timeout) yields an outcome with no components and one diagnostic, never an error: the structural result is
//! complete on its own.
//!
//! This slice answers function components by the exports the extractor recorded for them (a name, `default`, or the
//! property of an exported component a sub-component is attached to); a generic one whose first type parameter
//! declares a default is read at that default (`instantiate`). Class components, overloaded components and union props
//! types keep their structural result and say why.

#![deny(missing_docs)]

mod checker;
mod component;
mod convert;
mod declared;
mod instantiate;
mod locate;
mod on_demand;
mod printed;
mod rpc;
mod stamps;

pub use on_demand::{OnDemand, OnDemandConfig, Recycles, Snapshots};

use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::Duration;

use caliper_docgen_core::types::ExtractionOutput;
use caliper_docgen_core::types::semantic::{PropInterner, SemanticComponent, SemanticFallback, SemanticOutcome};
use camino::{Utf8Path, Utf8PathBuf};
use rustc_hash::FxHashMap;
use tokio::sync::Semaphore;
use tokio::task::JoinSet;

use crate::checker::{Backend, Start};
use crate::component::Answer;
use crate::convert::Converter;
use crate::instantiate::Instantiation;
use crate::rpc::{CallError, REQUESTS, Rpc};

/// The checker binaries a `tsc_path` may name, the builds whose protocol this backend was traced against (the built-in
/// checker is pinned in `Cargo.toml` instead): the `typescript` 7.1 series, from `7.1.0-beta` on, and the `tsrs` builds
/// listed exactly (`<tsrs version>-ts<typescript version>`), each only while its TypeScript part is in the series above.
/// The protocol has no version handshake, so the package's `package.json` version and the initialize call that follows
/// the spawn are the whole check; a build that fails either takes the structural result with one warning.
pub const SUPPORTED_VERSIONS: &[&str] = &["7.1", "0.23.0-ts7.1.0-beta"];

/// How many files are asked about at once. The checker answers requests one at a time; this keeps it from idling
/// between them.
const FILES_IN_FLIGHT: usize = 16;

/// A component the structural pass found.
pub use caliper_docgen_core::types::semantic::SemanticTarget as Target;

/// The components of `output`, in output order.
pub fn targets_of(output: &ExtractionOutput) -> Vec<Target> {
    output
        .components
        .iter()
        .map(|(key, entry)| Target {
            key: key.clone(),
            file_path: entry.file_path.clone(),
            display_name: entry.display_name.clone(),
            exports: entry.exports.clone(),
            described: entry
                .props
                .values()
                .filter(|prop| !prop.description.is_empty())
                .map(|prop| prop.name.clone())
                .collect(),
            // The whole-project merge leaves `@types/react`'s props to the inheritance layers.
            react_wanted: Some(Default::default()),
        })
        .collect()
}

/// One whole-project request to the checker: the components to answer for, and which checker to ask. Built with
/// [`SemanticRequest::new`] and answered by [`resolve`].
#[derive(Debug, Clone)]
pub struct SemanticRequest {
    /// Where the checker finds `node_modules`: its working directory.
    pub project_root: Utf8PathBuf,
    /// A tsconfig whose compiler options the checker uses (read with `parseConfigFile`); with none, a default set.
    pub tsconfig: Option<Utf8PathBuf>,
    /// A checker binary to run as a `tsc --api` process (`typescript@7.1`'s `tsc`, or `tsrs`) instead of the built-in
    /// checker.
    pub tsc_path: Option<Utf8PathBuf>,
    /// The components to ask about.
    pub targets: Vec<Target>,
    /// Bound on each request, and on a checker process's start-up handshake.
    pub request_timeout: Duration,
    /// The versions a checker binary's `package.json` may declare; one that is not among them is a start-up failure.
    /// The built-in checker is pinned and not checked.
    pub expected_versions: &'static [&'static str],
    /// Write every request and its answer here as JSON, to refresh the replay fixture the tests use.
    pub record_to: Option<Utf8PathBuf>,
    /// Environment for a checker process; the tests use it to pick a replay scenario.
    pub extra_env: Vec<(String, String)>,
    /// Ask the checker about a component's props, and about the members of each type, last to first. The answer must
    /// not change: no id the checker hands out, and so no order of queries, may show in it. The tests set this.
    pub reverse_queries: bool,
}

impl SemanticRequest {
    /// A request for `targets` under `project_root`, with a 60 second timeout, the supported versions, and no
    /// tsconfig or explicit `tsc` path.
    pub fn new(project_root: Utf8PathBuf, targets: Vec<Target>) -> Self {
        Self {
            project_root,
            tsconfig: None,
            tsc_path: None,
            targets,
            request_timeout: Duration::from_secs(60),
            expected_versions: SUPPORTED_VERSIONS,
            record_to: None,
            extra_env: Vec::new(),
            reverse_queries: false,
        }
    }
}

/// Resolves the request's components with the checker. Blocks; builds its own single-threaded runtime, so it must
/// not be called from inside one.
pub fn resolve(request: SemanticRequest) -> SemanticOutcome {
    let runtime = match tokio::runtime::Builder::new_current_thread().enable_all().build() {
        Ok(runtime) => runtime,
        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
    };
    runtime.block_on(run(request))
}

/// The exported targets by file, in first-seen order, and an outcome that already holds a fallback for each target
/// the checker cannot be asked about.
fn group_by_file(request: &SemanticRequest) -> (SemanticOutcome, FxHashMap<&Utf8Path, Vec<&Target>>, Vec<&Utf8Path>) {
    let mut outcome = SemanticOutcome::default();
    let mut by_file: FxHashMap<&Utf8Path, Vec<&Target>> = FxHashMap::default();
    let mut order: Vec<&Utf8Path> = Vec::new();
    for target in &request.targets {
        if target.exports.is_empty() {
            outcome.fallbacks.push(fallback_of(target, "not exported by its module"));
            continue;
        }
        let group = by_file.entry(target.file_path.as_path()).or_default();
        if group.is_empty() {
            order.push(target.file_path.as_path());
        }
        group.push(target);
    }
    (outcome, by_file, order)
}

/// The checker `request` names: its `tsc_path` as a process, else the built-in one.
async fn start_checker(request: &SemanticRequest) -> Result<Backend, String> {
    Backend::start(Start {
        project_root: &request.project_root,
        tsc_path: request.tsc_path.as_deref(),
        expected_versions: request.expected_versions,
        timeout: request.request_timeout,
        extra_env: &request.extra_env,
    })
    .await
}

async fn run(request: SemanticRequest) -> SemanticOutcome {
    if request.targets.iter().all(|target| target.exports.is_empty()) {
        return group_by_file(&request).0;
    }
    let checker = match start_checker(&request).await {
        Ok(checker) => checker,
        Err(reason) => return SemanticOutcome::unavailable(reason),
    };
    let outcome = answer_with(&checker, &request).await;
    checker.shutdown().await;
    outcome
}

/// The files of the request's exported targets, in first-seen order: the roots of the program that answers it.
fn root_files(request: &SemanticRequest) -> Vec<String> {
    group_by_file(request).2.iter().map(|file| file.to_string()).collect()
}

/// Answers the request's targets with a checker that is already running: one program rooted at their files, released
/// once they are answered.
async fn answer_with(checker: &Backend, request: &SemanticRequest) -> SemanticOutcome {
    let files = root_files(request);
    if files.is_empty() {
        return group_by_file(request).0;
    }
    let started = std::time::Instant::now();
    let tsconfig = request.tsconfig.as_ref().map(|path| path.as_str());
    let opened =
        Rpc::open(checker.client(), request.request_timeout, tsconfig, &files, request.record_to.is_some()).await;
    let rpc = match opened {
        Ok(rpc) => Arc::new(rpc),
        Err(error) => return SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
    };
    tracing::debug!(program_ms = started.elapsed().as_millis() as u64, "semantic program built");
    let answered = answer_on(&rpc, request, &files).await;
    rpc.release().await;
    answered.unwrap_or_else(|error| SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")))
}

/// Answers the request's targets on a snapshot whose program is rooted at `files` ([`root_files`]). The snapshot is
/// left as it is, for the caller to keep or release.
async fn answer_on(rpc: &Arc<Rpc>, request: &SemanticRequest, files: &[String]) -> Result<SemanticOutcome, CallError> {
    let (mut outcome, by_file, order) = group_by_file(request);
    let mut answered = session(rpc, request, files, &by_file, &order).await?;
    outcome.components.append(&mut answered.components);
    outcome.fallbacks.append(&mut answered.fallbacks);
    Ok(outcome)
}

async fn session(
    rpc: &Arc<Rpc>,
    request: &SemanticRequest,
    files: &[String],
    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
    order: &[&Utf8Path],
) -> Result<SemanticOutcome, CallError> {
    let started = std::time::Instant::now();
    let converter = Converter::new(rpc.clone(), request.reverse_queries);
    let limit = Arc::new(Semaphore::new(FILES_IN_FLIGHT));
    let interner = Arc::new(PropInterner::default());

    let mut tasks = JoinSet::new();
    for file in order {
        let targets: Vec<Target> = by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect();
        let (rpc, converter, limit, interner) = (rpc.clone(), converter.clone(), limit.clone(), interner.clone());
        tasks.spawn(async move {
            let _permit = limit.acquire().await;
            answer_file(&rpc, &converter, &interner, targets).await
        });
    }

    let mut outcome = SemanticOutcome::default();
    let mut generic = Vec::new();
    let mut failure = None;
    while let Some(joined) = tasks.join_next().await {
        match joined {
            Ok(Ok((mut answered, mut instantiations))) => {
                outcome.components.append(&mut answered.components);
                outcome.fallbacks.append(&mut answered.fallbacks);
                generic.append(&mut instantiations);
            }
            Ok(Err(error)) => {
                failure = Some(error);
                tasks.abort_all();
            }
            // A panic inside a worker must not silently leave its components structural.
            Err(joined) if joined.is_panic() => {
                failure = Some(CallError::Fatal("a worker panicked".to_string()));
                tasks.abort_all();
            }
            // A cancelled task is one this loop aborted after a failure.
            Err(_cancelled) => {}
        }
    }
    if let Some(error) = failure {
        return Err(error);
    }
    if !generic.is_empty() {
        let mut instantiated =
            instantiate::answer(rpc, files, &request.project_root, &interner, request.reverse_queries, generic).await?;
        outcome.components.append(&mut instantiated.components);
        outcome.fallbacks.append(&mut instantiated.fallbacks);
    }

    if let (Some(path), Some(recording)) = (&request.record_to, rpc.recording())
        && let Ok(json) = serde_json::to_string_pretty(&recording)
        && let Err(error) = std::fs::write(path, json)
    {
        tracing::warn!("could not write the recording to {path}: {error}");
    }
    tracing::debug!(
        requests = ?rpc.calls(),
        files = files.len(),
        type_memo = ?converter.memo_stats(),
        total_ms = started.elapsed().as_millis() as u64,
        "semantic backend finished"
    );
    outcome.components.sort_by(|a, b| a.key.cmp(&b.key));
    outcome.fallbacks.sort_by(|a, b| a.key.cmp(&b.key));
    Ok(outcome)
}

fn fallback_of(target: &Target, reason: &str) -> SemanticFallback {
    SemanticFallback { key: target.key.clone(), reason: reason.to_string() }
}

/// A fatal error aborts the run; a call the checker rejected only sends that component to its structural result. The
/// generic components come back apart, to be answered from their instantiations once every file is done.
async fn answer_file(
    rpc: &Rpc,
    converter: &Converter,
    interner: &PropInterner,
    targets: Vec<Target>,
) -> Result<(SemanticOutcome, Vec<(Target, Instantiation)>), CallError> {
    let mut outcome = SemanticOutcome::default();
    let mut generic = Vec::new();
    let Some(first) = targets.first() else { return Ok((outcome, generic)) };
    let module = match module_exports(rpc, first.file_path.as_str()).await {
        Ok(Some(module)) => module,
        Ok(None) | Err(CallError::Rejected(_)) => {
            outcome
                .fallbacks
                .extend(targets.iter().map(|target| fallback_of(target, "not part of the checker's program")));
            return Ok((outcome, generic));
        }
        Err(fatal) => return Err(fatal),
    };

    for target in &targets {
        let requests = Arc::new(AtomicU64::new(0));
        let started = std::time::Instant::now();
        let answered =
            REQUESTS.scope(requests.clone(), component::props_of(rpc, converter, interner, &module, target)).await;
        tracing::debug!(
            component = %target.display_name,
            requests = requests.load(Ordering::Relaxed),
            ms = started.elapsed().as_millis() as u64,
            "semantic component answered"
        );
        match answered {
            Ok(Answer::Props(component::Props { props, composes })) => {
                outcome.components.push(SemanticComponent { key: target.key.clone(), props, composes });
            }
            Ok(Answer::Fallback(reason)) => outcome.fallbacks.push(fallback_of(target, &reason)),
            Ok(Answer::Instantiate(instantiation)) => generic.push((target.clone(), instantiation)),
            Err(CallError::Rejected(message)) => {
                outcome.fallbacks.push(fallback_of(target, &format!("the checker rejected a request: {message}")));
            }
            Err(fatal) => return Err(fatal),
        }
    }
    Ok((outcome, generic))
}

/// The module `file` is, as the checker reads it, with its exports; `None` when the file is not in its program.
async fn module_exports(rpc: &Rpc, file: &str) -> Result<Option<component::Module>, CallError> {
    let Some(symbol) = rpc.source_file_symbol(file).await? else { return Ok(None) };
    let exports = rpc.exports_of_module(&symbol.reference).await?;
    Ok(Some(component::Module { symbol, exports }))
}

