48	/// Nesting past which an object, union or intersection is cut with [`TruncationLimit::Depth`].
49	const MAX_DEPTH: u8 = 5;
50	/// The most properties an object type lists at the top (a prop's own type) and below it that the project did not declare
51	/// itself (see [`is_own`]): what it declared is never cut.
52	const MAX_FIELDS: [usize; 2] = [100, 40];
53	/// The most members a union or intersection lists at the top and below it.
54	const MAX_MEMBERS: [usize; 2] = [500, 120];
55	/// How many of React's tag names (see [`is_tag`]) a union has to list to be React's `ElementType` (`JSX.IntrinsicElements`
56	/// has over 170): the tag names are the one part of it that no declaration identifies.
57	const MIN_INTRINSIC_TAGS: usize = 100;
58	/// The lib's utility aliases that keep the properties of the type they are applied to, and so can stand for it.
59	const UTILITIES: [&str; 5] = ["Omit", "Pick", "Partial", "Required", "Readonly"];
60	
61	/// What a descent found at [`Converter::enter`].
62	enum Gate<T> {
63	    /// The type is not expanded: it is a back-reference, or a cap cut it.
64	    Stop(PropType),
65	    /// The parts of the type, and the context to convert them in.
66	    Open { parts: T, inner: Cx },
67	}
68	
69	type Converted<'a> = Pin<Box<dyn Future<Output = Result<PropType, CallError>> + Send + 'a>>;
70	
71	/// What an object's members are known as when its type is entered.
72	enum Listed {
73	    /// The checker was asked for them.
74	    Members(ObjectMembers),
75	    /// How many properties an earlier map over the same keys had, none of them the project's (see [`State::maps`]). It
76	    /// is only handed out where that is more than the budget allows, so the type is cut and no list is needed.
77	    Counted(usize),
78	}
79	
80	/// What [`Converter::over_budget`] reads of the members of an object it cuts.
81	struct Excess {
82	    /// The type has call or construct signatures.
83	    signatures: bool,
84	    /// How many of its properties the project did not declare.
85	    outside: usize,
86	    /// The properties the project declared.
87	    own: Vec<SymbolInfo>,
88	    indexes: Vec<IndexInfo>,
89	}
90	
91	impl Excess {
92	    fn of(members: ObjectMembers) -> Self {
93	        let ObjectMembers { calls, constructs, properties, indexes } = members;
94	        let (own, outside): (Vec<SymbolInfo>, Vec<SymbolInfo>) = properties.into_iter().partition(is_own);
95	        Excess { signatures: !calls.is_empty() || !constructs.is_empty(), outside: outside.len(), own, indexes }
96	    }
97	
98	    fn counted(outside: usize) -> Self {
99	        Excess { signatures: false, outside, own: Vec::new(), indexes: Vec::new() }
100	    }
101	}
102	
103	/// What a map is remembered by: its constraint, as the checker's type handle, and the symbol that declares it.
104	type MapKey = (u64, CompactSymbol);
105	
106	/// The key of a mapped type whose property count another map over the same keys can answer for: one no name stands for
107	/// (an alias's arguments, `Partial<A>`, are what its properties come from, and the key holds none), with no `as` clause
108	/// (which would rename the keys).
109	fn map_key(info: &TypeInfo, origin: Option<&Origin>) -> Option<MapKey> {
110	    if origin.is_some() || info.object_flags & flag::OBJECT_MAPPED == 0 || info.name_type.is_some() {
111	        return None;
112	    }
113	    Some((info.constraint_type?, info.symbol.clone()?))
114	}
115	
116	/// The number of properties of a map's listed members to remember, when the cut of another map over the same keys needs
117	/// no more of them: the project declared none, so none is listed, and the map has no signature and no index signature,
118	/// whose types are another map's own.
119	fn settled_count(members: &ObjectMembers) -> Option<usize> {
120	    let bare = members.calls.is_empty() && members.constructs.is_empty() && members.indexes.is_empty();
121	    (bare && members.properties.iter().all(|property| !is_own(property))).then_some(members.properties.len())
122	}
123	
124	/// Where a type sits: how deep, and which named instantiations (an alias or interface with its type arguments, as the
125	/// checker's type handle) enclose it, outermost first.
126	#[derive(Debug, Clone, Default)]
127	pub(crate) struct Cx {
128	    depth: u8,
129	    enclosing: Arc<Vec<u64>>,
130	    /// The conversion this context belongs to, which records which enclosing instantiations it asks about. `None` at
131	    /// the roots.
132	    frame: Option<Arc<Frame>>,
133	}
134	
135	/// What one conversion has asked of the instantiations enclosing it, kept to build its memo entry (see
136	/// [`State::memo`]).
137	#[derive(Debug)]
138	struct Frame {
139	    /// How many instantiations enclosed the type when its conversion began: those below this are the outer context, the
140	    /// rest were opened by the conversion itself.
141	    base: usize,
142	    asked: Mutex<Asked>,
143	}
144	
145	#[derive(Debug, Default)]
146	struct Asked {
147	    /// The handles this conversion's own gate compared against its enclosing instantiations.
148	    ids: Vec<u64>,
149	    /// The sets asked by the conversions of its parts, each with the instantiations this conversion had opened by then:
150	    /// those were answered inside it and do not depend on its outer context.
151	    parts: Vec<(Arc<[u64]>, Vec<u64>)>,
152	}
153	
154	impl Frame {
155	    fn new(base: usize) -> Self {
156	        Frame { base, asked: Mutex::default() }
157	    }
158	
159	    fn lock(&self) -> std::sync::MutexGuard<'_, Asked> {
160	        self.asked.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
161	    }
162	
163	    fn ask(&self, id: u64) {
164	        self.lock().ids.push(id);
165	    }
166	
167	    /// A part of this conversion was converted (or recalled) under `enclosing`, having asked about `asked`.
168	    fn absorb(&self, asked: &Arc<[u64]>, enclosing: &[u64]) {
169	        if !asked.is_empty() {
170	            self.lock().parts.push((asked.clone(), enclosing.get(self.base..).unwrap_or_default().to_vec()));
171	        }
172	    }
173	
174	    /// Every handle the conversion asked about whose answer came from outside it: sorted, once each.
175	    fn finish(&self) -> Arc<[u64]> {
176	        let asked = self.lock();
177	        let mut ids = asked.ids.clone();
178	        for (part, opened) in &asked.parts {
179	            ids.extend(part.iter().copied().filter(|id| !opened.contains(id)));
180	        }
181	        ids.sort_unstable();
182	        ids.dedup();
183	        ids.into()
184	    }
185	}
186	
187	impl Cx {
188	    /// The context of what a name carries, its type arguments: one level down. Each argument is converted on its own
189	    /// and passes [`Converter::enter`] if it has parts.
190	    fn argument(&self) -> Cx {
191	        Cx { depth: self.depth.saturating_add(1), enclosing: self.enclosing.clone(), frame: self.frame.clone() }
192	    }
193	
194	    /// The context of the parts of a type that [`Converter::enter`] has admitted. Only a named instance is kept, since
195	    /// only a name can be pointed back to.
196	    fn below(&self, instance: Option<u64>) -> Cx {
197	        let mut enclosing = self.enclosing.clone();
198	        if let Some(id) = instance
199	            && !enclosing.contains(&id)
200	        {
201	            let mut grown = (*enclosing).clone();
202	            grown.push(id);
203	            enclosing = Arc::new(grown);
204	        }
205	        Cx { depth: self.depth.saturating_add(1), enclosing, frame: self.frame.clone() }
206	    }
207	
208	    /// Whether `id` is an instantiation being expanded around the type. The conversion in progress is recorded to have
209	    /// asked, whichever the answer.
210	    fn encloses(&self, id: u64) -> bool {
211	        if let Some(frame) = &self.frame {
212	            frame.ask(id);
213	        }
214	        self.enclosing.contains(&id)
215	    }
216	
217	    fn limit<const N: usize>(&self, limits: [usize; N]) -> usize {
218	        limits[usize::from(self.depth > 0).min(N - 1)]
219	    }
220	}
221	
222	/// What declares a type: the alias it was written through, else its interface or class.
223	#[derive(Debug, Clone)]
224	struct Origin {
225	    name: String,
226	    /// The declaring file as the checker keys it (lower-cased path).
227	    file: String,
228	    alias: bool,
229	}
230	
231	impl Origin {
232	    fn of(symbol: &SymbolInfo, alias: bool) -> Self {
233	        let declaration = symbol.declarations.first().map(String::as_str);
234	        Origin {
235	            name: symbol.name.clone(),
236	            file: declaration.map(|declaration| declared_in(declaration).to_string()).unwrap_or_default(),
237	            alias,
238	        }
239	    }
240	
241	    fn in_dependency(&self) -> bool {
242	        file_in_dependency(&self.file)
243	    }
244	
245	    fn in_lib(&self) -> bool {
246	        file_in_lib(&self.file)
247	    }
248	
249	    fn in_react(&self) -> bool {
250	        self.file.contains("/@types/react/")
251	    }
252	
253	    /// Whether the name stands for the type: declared in a dependency, or an interface or class of the lib. An alias
254	    /// of the lib is a type-level function (`Partial<T>`), and its result is the type.
255	    fn is_boundary(&self) -> bool {
256	        // The lib may itself sit under `node_modules` (`typescript/lib`, `@tsrs/<platform>`).
257	        if self.in_lib() { !self.alias } else { self.in_dependency() }
258	    }
259	
260	    /// The React type that PropType holds as a terminal, found by the declaration and not by how it prints.
261	    fn react_terminal(&self) -> Option<PropType> {
262	        if !self.in_react() {
263	            return None;
264	        }
265	        match (self.name.as_str(), self.alias) {
266	            ("ReactNode", true) | ("ReactElement" | "Element", false) => Some(PropType::ReactNode),
267	            ("ElementType", true) => Some(PropType::ElementType),
268	            ("CSSProperties", false) => Some(PropType::CssProperties),
269	            _ => None,
270	        }
271	    }
272	}
273	
274	/// Whether a union member is a tag of React's `JSX.IntrinsicElements`: a string literal (not an enum member) whose value
275	/// that table lists. A literal the checker gave no value for is not one, so it is kept beside the terminal.
276	fn is_tag(member: &TypeInfo) -> bool {
277	    member.flags & flag::STRING_LITERAL != 0
278	        && member.flags & flag::ENUM_LITERAL == 0
279	        && member.value.as_ref().and_then(|value| value.as_str()).is_some_and(is_intrinsic_tag)
280	}
281	
282	/// Whether the checker states the base types of this type in its own terms: the declaration of a class or interface
283	/// does. An instantiation of a generic one (`Box<string>`, only a reference) does not state them in terms of its
284	/// arguments, so a traversal that keeps the arguments cannot list what it inherits; one that wants only names reads the
285	/// generic type instead ([`Converter::named_bases`]).
286	fn states_bases(info: &TypeInfo) -> bool {
287	    info.object_flags & (flag::OBJECT_CLASS | flag::OBJECT_INTERFACE) != 0
288	}
289	
290	/// Where the base types of a type are to be asked, from what the checker says of the type itself.
291	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
292	enum BasesOf {
293	    /// A class or interface declaration: the checker states them ([`states_bases`]).
294	    Itself,
295	    /// An instantiation of a generic type: its generic target states them.
296	    Generic,
297	    /// An object type no class or interface declares (a type literal, a mapped type): it has none.
298	    None,
299	    /// A union, a type parameter or any other type the checker was not asked about: whether it has bases is not known.
300	    Unknown,
301	}
302	
303	impl BasesOf {
304	    fn of(info: &TypeInfo) -> Self {
305	        if states_bases(info) {
306	            Self::Itself
307	        } else if info.object_flags & flag::OBJECT_REFERENCE != 0 {
308	            Self::Generic
309	        } else if info.flags & flag::OBJECT != 0 {
310	            Self::None
311	        } else {
312	            Self::Unknown
313	        }
314	    }
315	}
