317	fn file_in_dependency(file: &str) -> bool {
318	    file.contains("/node_modules/")
319	}
320	
321	fn file_in_lib(file: &str) -> bool {
322	    let name = file.rsplit('/').next().unwrap_or("");
323	    name.starts_with("lib.") && name.ends_with(".d.ts")
324	}
325	
326	/// Whether a property is the project's own: its first declaration is in a file of the project, not a dependency or the
327	/// lib. A property with no declaration (a mapped type's synthetic one) is not, so a wide mapped type is still cut.
328	fn is_own(property: &SymbolInfo) -> bool {
329	    property.declarations.first().is_some_and(|declaration| {
330	        let file = declared_in(declaration);
331	        !file_in_dependency(file) && !file_in_lib(file)
332	    })
333	}
334	
335	/// `declarations` entries read `"<node index>.<kind>.<path>"`: the path is lower-cased, as the checker keys files.
336	pub(crate) fn declared_in(declaration: &str) -> &str {
337	    declaration.splitn(3, '.').nth(2).unwrap_or("")
338	}
