340	/// A converted type, with the enclosing instantiations its conversion depended on.
341	#[derive(Debug)]
342	struct Entry {
343	    /// Every handle the conversion compared against the instantiations enclosing it, sorted.
344	    asked: Arc<[u64]>,
345	    /// Those of `asked` that did enclose it.
346	    enclosed_by: Vec<u64>,
347	    converted: PropType,
348	}
349	
350	impl Entry {
351	    /// Whether the conversion would go the same way inside `enclosing`: among the handles it asked about, the ones
352	    /// that enclose the type there are exactly `enclosed_by`.
353	    fn holds_in(&self, enclosing: &[u64]) -> bool {
354	        self.enclosed_by.iter().all(|id| enclosing.contains(id))
355	            && enclosing.iter().all(|id| self.enclosed_by.contains(id) || self.asked.binary_search(id).is_err())
356	    }
357	}
358	
359	type Memo = Mutex<FxHashMap<(u64, u8), Vec<Arc<Entry>>>>;
360	
361	/// The parts of each type asked about so far, by (type handle, which parts), as the text the checker answered: read
362	/// again on each use, which costs a fraction of the round trip, and is several times smaller than the read lists.
363	type PartsSeen = Mutex<FxHashMap<(u64, Parts), Arc<RawValue>>>;
364	
365	/// Which parts of a type [`Converter::parts`] asks for.
366	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
367	enum Parts {
368	    /// A union's, intersection's or template literal's members (`getTypesOfType`).
369	    Members,
370	    /// A reference's type arguments (`getTypeArguments`), the `this` type the checker appends included.
371	    Arguments,
372	}
373	
374	/// The type arguments a reference names, without the `this` type the checker appends to a class's or interface's.
375	fn without_this(arguments: &[TypeInfo]) -> &[TypeInfo] {
376	    let named = arguments.iter().rposition(|argument| !argument.is_this_type).map_or(0, |last| last + 1);
377	    arguments.get(..named).unwrap_or_default()
378	}
379	
380	#[derive(Default)]
381	struct State {
382	    /// Conversions by (type handle, depth), each entry with the enclosing instantiations it depended on. The handles
383	    /// are valid inside this snapshot only.
384	    ///
385	    /// Why an entry may be reused where [`Entry::holds_in`] says. A conversion reads its context in two ways only: the
386	    /// depth, which is in the key, and [`Cx::encloses`], the question whether a handle is an instantiation being
387	    /// expanded around the type. Everything else it reads is the checker's answer about the type, which does not change
388	    /// inside a snapshot. So a conversion is a deterministic walk whose every step is fixed by the type, the depth and
389	    /// the answers to those questions, in the order they are asked. Run it again where each handle it asked about has
390	    /// the same answer, and it asks the same questions in the same order and returns the same type. A handle that the
391	    /// conversion opened itself is settled inside it (it was found not to enclose the type at its own gate, which is
392	    /// recorded), so only the handles asked of the outer context are kept. A type in no cycle with its context asks
393	    /// nothing that encloses it and holds everywhere; one in a cycle holds where the same part of the cycle encloses
394	    /// it. Entries that hold in a context all agree, so which of them is found first, and so the order in which
395	    /// types were first reached, cannot show in the output.
396	    memo: Memo,
397	    origins: Mutex<FxHashMap<(bool, CompactSymbol), Option<Origin>>>,
398	    /// By (type handle, whether printed expanded: see [`Rpc::type_to_string_expanded`]).
399	    printed: Mutex<FxHashMap<(u64, bool), String>>,
400	    /// The parts of a type by its handle (see [`Parts`]). They are the checker's answer about the type, fixed inside the
401	    /// snapshot, while the memo converts a type again at another depth or under other instantiations: kept, that
402	    /// conversion asks for none of them again. Kept for the whole snapshot, since components of one library share
403	    /// most of their types: kept per component, a program of every Chakra component answered 16 at a time held 16
404	    /// copies of the same style props' members.
405	    parts: PartsSeen,
406	    /// Where props are declared ([`crate::declared`]), kept for the snapshot like the rest.
407	    declared: crate::declared::Memo,
408	    /// A map's property count by [`MapKey`]: a map without `as` has one property per key of its constraint and a cut reads
409	    /// only that count, so a [`settled_count`] list stands for every map of its key (docs/type-checker-integration.md,
410	    /// "Condition maps", says when that is exact). The handles are valid inside this snapshot only.
411	    maps: Mutex<FxHashMap<MapKey, usize>>,
412	    hits: AtomicU64,
413	    misses: AtomicU64,
414	}
415	
416	#[derive(Clone)]
417	pub(crate) struct Converter {
418	    rpc: Arc<Rpc>,
419	    state: Arc<State>,
420	    /// Ask the checker about the members of a type last to first. The answer is the same, and a test holds it to that.
421	    reverse: bool,
422	}
423	
424	impl Converter {
425	    pub(crate) fn new(rpc: Arc<Rpc>, reverse: bool) -> Self {
426	        Self { rpc, state: Arc::new(State::default()), reverse }
427	    }
428	
429	    /// Every type converted, in the order of `infos`, though when `reverse` is set the checker is asked last to first.
430	    async fn convert_all(&self, infos: &[TypeInfo], cx: &Cx) -> Result<Vec<PropType>, CallError> {
431	        let mut slots: Vec<Option<PropType>> = vec![None; infos.len()];
432	        let order: Box<dyn Iterator<Item = usize> + Send> =
433	            if self.reverse { Box::new((0..infos.len()).rev()) } else { Box::new(0..infos.len()) };
434	        for index in order {
435	            if let (Some(info), Some(slot)) = (infos.get(index), slots.get_mut(index)) {
436	                *slot = Some(self.convert(info, cx).await?);
437	            }
438	        }
439	        Ok(slots.into_iter().flatten().collect())
440	    }
441	
442	    /// Memo hits and misses so far, for the debug line.
443	    pub(crate) fn memo_stats(&self) -> (u64, u64) {
444	        (self.state.hits.load(Ordering::Relaxed), self.state.misses.load(Ordering::Relaxed))
445	    }
446	
447	    /// The own types of a component's props, from the top.
448	    pub(crate) async fn convert_roots(&self, infos: &[TypeInfo]) -> Result<Vec<PropType>, CallError> {
449	        self.convert_all(infos, &Cx::default()).await
450	    }
451	
452	    /// Where each prop of `asked` is declared and what its JSDoc says ([`crate::declared`]).
453	    pub(crate) async fn declared(&self, asked: &[crate::declared::Asked<'_>]) -> Result<Vec<Declared>, CallError> {
