26	/// The type of a name the checker could not resolve (an import that does not resolve, a name declared nowhere), which
27	/// the checker answers with its error type: an `any` that is not a written `any`. It is `opaque` with the reason
28	/// `unresolvableImport`, so the prop carries `degradedBy`, and `written` is the name as the source writes it, which is
29	/// also what the reason names (the checker does not say which module specifier was behind it).
30	pub fn unresolved_type(written: impl Into<String>) -> PropType {
31	    let written = written.into();
32	    #[allow(
33	        clippy::disallowed_methods,
34	        reason = "the checker's error type is an unresolvable name; the caller reports it"
35	    )]
36	    OpaqueDetail::new(written.clone(), OpaqueReason::UnresolvableImport { specifier: written })
37	}
38	
39	/// A type the checker holds that PropType has no shape for: a conditional or indexed access type it could not resolve
40	/// (its parameters are still open), `keyof T`. It is `opaque` with `reason`, so the prop carries `degradedBy`, and
41	/// `raw` is how the checker prints it.
42	pub fn degraded_type(raw: impl Into<String>, reason: OpaqueReason) -> PropType {
43	    #[allow(clippy::disallowed_methods, reason = "the checker names the reason; the caller reports it")]
44	    OpaqueDetail::new(raw, reason)
45	}
