47	/// One prop as the checker reports it.
48	#[derive(Debug, Clone, PartialEq)]
49	pub struct SemanticProp {
50	    /// The prop's name as written in the props type.
51	    pub name: String,
52	    /// The type the checker computed for it, in the same shape the structural resolver produces.
53	    pub prop_type: PropType,
54	    /// Whether the checker found the prop non-optional.
55	    pub required: bool,
56	    /// The prop's JSDoc description, empty when it has none; the merge then keeps the structural description.
57	    pub description: String,
58	    /// The prop's JSDoc tags (`@deprecated`, `@since`, `@default`), each by name with the text the checker renders, empty
59	    /// when it has none; the merge then keeps the structural tags, as for `description`. `@types/react`'s props are not
60	    /// asked for theirs.
61	    pub tags: BTreeMap<String, String>,
62	    /// The interface that declares the prop, as react-docgen-typescript states it: the parent of its first declaration
63	    /// when that is an interface, with the file it is in. `None` for a prop declared in a type literal or with no
64	    /// declaration. It replaces the structural `parent`, `None` included.
65	    pub parent: Option<PropParent>,
66	    /// The interface of each declaration that is in one, in the checker's order: two when an intersection or a merged
67	    /// interface declares the prop twice.
68	    pub declarations: Vec<PropParent>,
69	    /// Declared by `@types/react` (`children`, `aria-*`, handlers, `className`): not the component's own prop.
70	    pub react_declared: bool,
71	}
