339	/// How a merge went for one component.
340	#[derive(Debug, Clone, Default, PartialEq)]
341	pub struct MergedProps {
342	    /// Structural props the checker did not return, kept as the structural pass resolved them.
343	    pub kept: usize,
344	    /// Props the checker returned with a type it could not read (an `opaque` part: an import that does not resolve, a
345	    /// conditional type it left open), where the structural pass read the type in full. They keep the structural type,
346	    /// and their `degradedBy` also lists what the checker could not read.
347	    pub unread: usize,
348	    /// A source file the merge could not read for the defaults and union order of the answer.
349	    pub diagnostics: Vec<Diagnostic>,
350	}
