352	/// Merges the checker's `props` into `entry` by name: the checker's type, optionality, description, tags, `parent` and
353	/// `declarations` win where both have a prop, and every structural prop the checker did not return stays as the
354	/// structural pass resolved it. `composes` replaces the entry's when the checker decided it, and an undecided one leaves
355	/// the structural `composes` ([`SemanticComponent::composes`]). A prop whose checker
356	/// type holds an `opaque` part, where the structural type holds none, keeps the structural type and adds the checker's
357	/// reasons to its `degradedBy`: the checker's answer there is a placeholder, and the structural one is not confirmed,
358	/// so it is marked. A type the checker only cut at a limit (`truncated`) is still its answer.
359	///
360	/// Two facts the checker does not have come from oxc's syntax, read from the files the answer names: a prop's default
361	/// (the component's code: a destructured parameter's initializer, `defaultProps`; else the checker's `@default` tag)
362	/// and the order of a union's members (the order its declaration writes them in). The structural answer gives them
363	/// where the syntax does not tell ([`ResolverFacts::Used`]).
364	pub fn merge_semantic_props<'a>(
365	    entry: &mut ComponentEntry,
366	    props: impl Iterator<Item = &'a Arc<SemanticProp>>,
367	    composes: Option<&[String]>,
368	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
369	) -> MergedProps {
370	    let props: Vec<Arc<SemanticProp>> = props.cloned().collect();
371	    let syntax = SourceSyntax::read(std::iter::once((&*entry, props.as_slice())));
372	    let merge = Merge { composes, unanswered: Unanswered::Keep, syntax: &syntax, resolver: ResolverFacts::Used };
373	    let mut merged = replace_props(entry, props.iter(), &merge, shared);
374	    merged.diagnostics = syntax.diagnostics;
375	    merged
376	}
