378	/// The kinds of what the checker could not read in `checker`, when the structural type `structural` read everything:
379	/// then the structural type is kept and marked with them. Empty when the checker's type is its answer.
380	fn unread_by_checker(checker: &PropType, structural: &PropType) -> Vec<&'static str> {
381	    let unread: Vec<&'static str> = checker.degraded_by().into_iter().filter(|kind| *kind != TRUNCATED_KIND).collect();
382	    if unread.is_empty() || structural.degraded_by().iter().any(|kind| *kind != TRUNCATED_KIND) {
383	        return Vec::new();
384	    }
385	    unread
386	}
