388	/// The one diagnostic for the props of `affects` that kept their structural type because the checker could not read it
389	/// ([`MergedProps::unread`]); each such prop says why in its `degradedBy`.
390	pub(crate) fn unread_diagnostic(props: usize, affects: Vec<String>) -> Diagnostic {
391	    let mut diagnostic = Diagnostic::new(
392	        DiagnosticSeverity::Info,
393	        DiagnosticCode::SemanticBackend,
394	        format!(
395	            "{props} prop(s) of {} component(s) keep their structural type: the TypeScript checker could not read it, \
396	             and their degradedBy says what it could not read",
397	            affects.len()
398	        ),
399	    );
400	    diagnostic.affects = affects;
401	    diagnostic
402	}
