404	/// A component the checker answered for, as [`drop_superseded`] reads it.
405	pub(crate) struct Superseding<'a> {
406	    key: &'a str,
407	    /// A structural prop the checker did not return still holds a part the structural pass could not read, which a
408	    /// structural diagnostic naming the component may be about.
409	    structural_left: bool,
410	    /// A prop of the merged answer holds a name the checker could not resolve either.
411	    unresolved: bool,
412	}
413	
414	impl<'a> Superseding<'a> {
415	    /// `key`'s component as `merged` holds it after the checker's props were merged in. `structural_left` says whether a
416	    /// structural prop the checker did not return still holds a part the structural pass could not read.
417	    pub(crate) fn new(key: &'a str, merged: &ComponentEntry, structural_left: bool) -> Self {
418	        let unresolved_kind = OpaqueReason::UnresolvableImport { specifier: String::new() }.kind();
419	        let unresolved = merged.props.values().any(|prop| prop.degraded_by.iter().any(|kind| kind == unresolved_kind));
420	        Self { key, structural_left, unresolved }
421	    }
422	
423	    fn supersedes(&self, superseded: Superseded) -> bool {
424	        match superseded {
425	            Superseded::No => false,
426	            Superseded::Yes => !self.structural_left,
427	            Superseded::UnlessUnresolvedByChecker => !self.structural_left && !self.unresolved,
428	        }
429	    }
430	}
