432	/// Takes the components the checker answered for out of the `affects` of each structural diagnostic its answer
433	/// supersedes ([`DiagnosticCode::superseded_by_checker`]), and drops a diagnostic left affecting no component. A
434	/// diagnostic that affected none (a file's, the run's) is about no component's props and stays. Both merges call it
435	/// before the checker's own diagnostics join `diagnostics`, so it reads only the structural pass's.
436	pub(crate) fn drop_superseded(diagnostics: &mut Vec<Diagnostic>, answered: &[Superseding<'_>]) {
437	    if answered.is_empty() {
438	        return;
439	    }
440	    let by_key: FxHashMap<&str, &Superseding<'_>> = answered.iter().map(|answer| (answer.key, answer)).collect();
441	    diagnostics.retain_mut(|diagnostic| {
442	        if diagnostic.affects.is_empty() {
443	            return true;
444	        }
445	        let superseded = diagnostic.code.superseded_by_checker();
446	        diagnostic.affects.retain(|key| by_key.get(key.as_str()).is_none_or(|answer| !answer.supersedes(superseded)));
447	        !diagnostic.affects.is_empty()
448	    });
449	}
