452	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
453	enum Unanswered {
454	    /// The checker decides which props exist, as in the whole-project merge: the structural prop is dropped.
455	    Drop,
456	    /// The checker's props are merged by name, as in a session's merge: the structural prop stays as resolved.
457	    Keep,
458	}
