466	}
467	
468	/// A prop's default: the component's code default for it, else the checker's `@default` (or `@defaultValue`) tag, else
469	/// with [`ResolverFacts::Used`] the structural default. The code wins over the tag, as in react-docgen-typescript.
470	fn default_of(
471	    code: Option<&DefaultValue>,
472	    checker_tags: &BTreeMap<String, String>,
473	    structural: Option<&ParsedProp>,
474	    resolver: ResolverFacts,
475	) -> Option<DefaultValue> {
476	    if let Some(code) = code {
477	        return Some(code.clone());
478	    }
479	    let tag = checker_tags.get("default").or_else(|| checker_tags.get("defaultValue"));
480	    if let Some(tag) = tag {
481	        return Some(DefaultValue { value: tag.trim().to_owned(), computed: false });
482	    }
483	    match resolver {
484	        ResolverFacts::Used => structural.and_then(|structural| structural.default_value.clone()),
485	        ResolverFacts::Off => None,
486	    }
487	}
488	
489	/// The checker's type with its union members in declared order: the order the declaration writes them in where it
490	/// states every member, else the structural union's order where that placed any member (with
491	/// [`ResolverFacts::Used`]), else the written order of the members the declaration does state. Neither leaves the
492	/// checker's order. A structural order that placed members is kept even where it is the checker's own: the partial
493	/// written order would put the members it does not state last, where they may not have been written.
494	fn declared_order(
495	    checker: PropType,
496	    written: Option<&[WrittenMember]>,
497	    structural: Option<&ParsedProp>,
498	    resolver: ResolverFacts,
499	) -> PropType {
500	    let structural = match resolver {
501	        ResolverFacts::Used => structural,
502	        ResolverFacts::Off => None,
503	    };
504	    // The structural order also reaches the unions nested in members, which the written one does not.
505	    let (ordered, placed) = match structural {
506	        Some(structural) => {
507	            let placed = order::places_any(&checker, &structural.prop_type);
508	            (order::in_declared_order(checker, &structural.prop_type), placed)
509	        }
510	        None => (checker, false),
511	    };
512	    match written.and_then(|written| order::in_written_order(&ordered, written)) {
513	        Some((in_written, Placed::All)) => in_written,
514	        Some((in_written, Placed::Some)) if !placed => in_written,
515	        Some(_) | None => ordered,
516	    }
517	}
518	
519	fn replace_props<'a>(
520	    entry: &mut ComponentEntry,
521	    props_in: impl Iterator<Item = &'a Arc<SemanticProp>>,
522	    merge: &Merge<'_>,
523	    shared: &mut FxHashMap<u64, Vec<Arc<ParsedProp>>>,
524	) -> MergedProps {
525	    let Merge { composes, unanswered, syntax, resolver } = *merge;
526	    let code_defaults = syntax.code_defaults(entry);
527	    let mut props: BTreeMap<String, Arc<ParsedProp>> = BTreeMap::new();
528	    let mut unread = 0;
529	    for prop in props_in {
530	        let structural = entry.props.get(&prop.name);
531	        let description = if prop.description.is_empty() {
532	            structural.map(|s| s.description.clone()).unwrap_or_default()
533	        } else {
534	            prop.description.clone()
535	        };
536	        let tags = if prop.tags.is_empty() {
537	            structural.map(|s| s.tags.clone()).unwrap_or_default()
538	        } else {
539	            prop.tags.clone()
540	        };
541	        let unread_kinds = structural.map(|s| unread_by_checker(&prop.prop_type, &s.prop_type)).unwrap_or_default();
542	        let prop_type = match structural {
543	            Some(structural) if !unread_kinds.is_empty() => structural.prop_type.clone(),
544	            Some(_) | None => {
545	                declared_order(prop.prop_type.clone(), syntax.written(entry, prop), structural.map(|s| &**s), resolver)
546	            }
547	        };
548	        unread += usize::from(!unread_kinds.is_empty());
549	        let merged = ParsedProp::new(
550	            prop.name.clone(),
551	            prop_type,
552	            prop.required,
553	            default_of(
554	                code_defaults.and_then(|defaults| defaults.get(&prop.name)),
555	                &prop.tags,
556	                structural.map(|s| &**s),
557	                resolver,
558	            ),
559	            description,
560	            tags,
561	            prop.parent.clone(),
562	            prop.declarations.clone(),
563	        )
564	        .degraded_also_by(&unread_kinds);
565	        let mut hasher = FxHasher::default();
566	        merged.structural_hash(&mut hasher);
567	        let bucket = shared.entry(hasher.finish()).or_default();
568	        let merged = match bucket.iter().find(|existing| ***existing == merged) {
569	            Some(existing) => existing.clone(),
570	            None => {
571	                let merged = Arc::new(merged);
572	                bucket.push(merged.clone());
573	                merged
574	            }
575	        };
576	        props.insert(prop.name.clone(), merged);
577	    }
578	    let mut kept = 0;
579	    if unanswered == Unanswered::Keep {
580	        for (name, structural) in &entry.props {
581	            if !props.contains_key(name) {
582	                props.insert(name.clone(), structural.clone());
583	                kept += 1;
584	            }
585	        }
586	    }
587	    entry.props = props;
588	    if let Some(composes) = composes {
589	        entry.composes = composes.to_vec();
590	    }
591	    MergedProps { kept, unread, diagnostics: Vec::new() }
592	}
593	
594	/// Merge the checker's props over `output`, component by component.
595	///
596	/// Per `docs/type-checker-integration.md`: the checker decides which props exist, their types, whether they are
597	/// required, `parent`, `declarations` and the component's `composes`; a description and tags come from the checker,
598	/// else the structural pass; a default value and a union's member order come from oxc's syntax, else the structural
599	/// pass ([`merge_semantic_props`]). Inheritance layers, curated inherited props and `discriminantProp` stay structural.
600	/// Components the checker did not answer for keep their structural result untouched. A structural diagnostic stops
601	/// naming a component the checker answered for when the answer supersedes it
602	/// ([`DiagnosticCode::superseded_by_checker`]), and goes once it names none.
603	///
604	/// Records provenance as `Info` diagnostics whose `affects` lists the output keys, so the canonical JSON gains no
605	/// field: one for the components the checker resolved, one per fallback reason.
606	pub fn merge_semantic(output: &mut ExtractionOutput, outcome: SemanticOutcome) {
607	    merge_semantic_with(output, outcome, ResolverFacts::Used);
608	}
609	
610	/// [`merge_semantic`], taking the facts the checker does not supply from the structural answer only as `resolver`
611	/// allows.
612	pub fn merge_semantic_with(output: &mut ExtractionOutput, outcome: SemanticOutcome, resolver: ResolverFacts) {
613	    let SemanticOutcome { components, fallbacks, diagnostics } = outcome;
614	    let syntax = SourceSyntax::read(
615	        components
616	            .iter()
617	            .filter_map(|semantic| Some((output.components.get(&semantic.key)?, semantic.props.as_slice()))),
618	    );
619	    let mut merged_keys = Vec::new();
620	    let (mut unread_keys, mut unread_props) = (Vec::new(), 0);
621	    let mut shared: FxHashMap<u64, Vec<Arc<ParsedProp>>> = FxHashMap::default();
622	    for semantic in components {
623	        let Some(entry) = output.components.get_mut(&semantic.key) else { continue };
624	        let unread = apply_props(entry, &semantic, &mut shared, &syntax, resolver).unread;
625	        if unread > 0 {
626	            unread_props += unread;
627	            unread_keys.push(semantic.key.clone());
628	        }
629	        merged_keys.push(semantic.key);
630	    }
631	    // The whole-project merge drops every structural prop the checker did not return, so none is left over.
632	    let answered: Vec<Superseding<'_>> =
633	        merged_keys.iter().filter_map(|key| Some(Superseding::new(key, output.components.get(key)?, false))).collect();
634	    drop_superseded(&mut output.diagnostics, &answered);
635	    output.diagnostics.extend(diagnostics);
636	    output.diagnostics.extend(syntax.diagnostics);
637	
638	    if !merged_keys.is_empty() {
639	        merged_keys.sort();
640	        let mut provenance = Diagnostic::new(
641	            DiagnosticSeverity::Info,
642	            DiagnosticCode::SemanticBackend,
643	            format!("{} component(s) resolved by the TypeScript checker", merged_keys.len()),
644	        );
645	        provenance.affects = merged_keys;
646	        output.diagnostics.push(provenance);
647	    }
648	    if !unread_keys.is_empty() {
649	        unread_keys.sort();
650	        output.diagnostics.push(unread_diagnostic(unread_props, unread_keys));
651	    }
652	
653	    let mut by_reason: BTreeMap<String, Vec<String>> = BTreeMap::new();
654	    for SemanticFallback { key, reason } in fallbacks {
655	        if output.components.contains_key(&key) {
656	            by_reason.entry(reason).or_default().push(key);
657	        }
658	    }
659	    for (reason, mut keys) in by_reason {
660	        keys.sort();
661	        let mut diagnostic = Diagnostic::new(
662	            DiagnosticSeverity::Info,
663	            DiagnosticCode::SemanticBackend,
664	            format!("{} component(s) kept their structural result: {reason}", keys.len()),
665	        );
666	        diagnostic.affects = keys;
667	        output.diagnostics.push(diagnostic);
668	    }
669	}
670	
671	#[cfg(test)]
672	mod tests;
673

