fn serve(cwd: String, queue: mpsc::Receiver<Job>, threads: usize) {
    let fs: Arc<dyn FS> = Arc::new(bundled::wrap_fs(osvfs::fs()));
    let session = Session::new(SessionOptions::new(cwd, bundled::lib_path(), fs, false));
