/// What the checker threads share.
struct Served {
    session: Arc<Session>,
    queue: Mutex<mpsc::Receiver<Job>>,
    /// Set by the thread that took [`Job::Stop`]: the others leave at their next look at the queue.
    stopping: AtomicBool,
    /// Threads still answering.
    left: AtomicUsize,
}

/// How long a thread waits for a request before it looks whether another thread was told to stop.
const STOP_POLL: Duration = Duration::from_millis(50);

impl Served {
    fn answer(&self) {
        while let Some(asked) = self.next() {
            // A caller that stopped waiting (its deadline passed, its run ended) is not answered.
            if asked.reply.is_closed() {
                continue;
            }
            let answer = match self.session.handle_request(&asked.method, &asked.params) {
                Ok(Response::Json(text)) => Ok(text),
                Ok(Response::Binary(_)) => Err(format!("{} answered in binary, not JSON", asked.method)),
                Err(error) => Err(error.to_string()),
            };
            asked.reply.send(answer).ok();
        }
        if self.left.fetch_sub(1, Ordering::AcqRel) == 1 {
            self.session.close();
        }
    }

    /// The next request, or `None` once the checker is stopped or every sender is gone.
    fn next(&self) -> Option<Asked> {
        loop {
            if self.stopping.load(Ordering::Acquire) {
                return None;
            }
            let queue = self.queue.lock().unwrap_or_else(std::sync::PoisonError::into_inner);
            match queue.recv_timeout(STOP_POLL) {
                Ok(Job::Request(asked)) => return Some(asked),
                Ok(Job::Stop) => {
                    self.stopping.store(true, Ordering::Release);
                    return None;
                }
                Err(mpsc::RecvTimeoutError::Timeout) => {}
                Err(mpsc::RecvTimeoutError::Disconnected) => return None,
            }
        }
    }
}

