"""Who waits: the callers of the leaf frames named on the command line, per checker thread. Usage: callers.py <prof> <thread-substr> <leaf>..."""
import bisect
import gzip
import json
import re
import sys
from collections import Counter

path, want, leaves = sys.argv[1], sys.argv[2], set(sys.argv[3:])
p = json.load(gzip.open(path))
syms = json.load(open(path.replace('.json.gz', '.json.syms.json')))
strings = syms['string_table']
libmap = {e['code_id']: sorted(e['symbol_table'], key=lambda x: x['rva']) for e in syms['data']}
starts = {k: [e['rva'] for e in v] for k, v in libmap.items()}


def name(lib, addr):
    code = p['libs'][lib].get('codeId')
    t = libmap.get(code)
    if not t:
        return '?'
    i = bisect.bisect_right(starts[code], addr) - 1
    return re.sub(r'<[^<>]*>', '', strings[t[i]['symbol']])[:110] if i >= 0 else '?'


for th in p['threads']:
    if want not in th['name']:
        continue
    ft, st = th['frameTable'], th['stackTable']
    fn = []
    for i in range(ft['length']):
        res = th['funcTable']['resource'][ft['func'][i]]
        lib = th['resourceTable']['lib'][res] if res is not None and res >= 0 else None
        fn.append(name(lib, ft['address'][i]) if lib is not None else '?')
    c = Counter()
    for s in th['samples']['stack']:
        if s is None:
            continue
        chain = []
        while s is not None:
            chain.append(fn[st['frame'][s]])
            s = st['prefix'][s]
        if chain[0] in leaves:
            c[' < '.join(chain[1:8])] += 1
    print(th['name'])
    for k, v in c.most_common(6):
        print(v, k)

